/* prog49_bst.c – rebuilt from the analysed binary
 *
 * Behaviour:
 *   prog49_bst MODE NUM1 NUM2 ...
 *
 *   MODE is one of: "in", "pre", "post"
 *   The numbers are inserted (in order) into a binary search tree.
 *   After all insertions the tree is traversed according to MODE and
 *   the values are printed separated by a single space, followed by a
 *   newline.  If the tree is empty the program prints "EMPTY" (and a
 *   newline).  If MODE is not recognised the program prints
 *   "INVALID_MODE" (and a newline).
 *
 *   The original binary limited the number of inserted values to 64
 *   when more than 66 arguments were supplied; this implementation
 *   follows the same rule for compatibility.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

/* Insert a value into the BST.  Duplicates are ignored. */
static void insert(Node **root, long v)
{
    if (*root == NULL) {
        Node *n = malloc(sizeof(Node));
        if (!n) { perror("malloc"); exit(EXIT_FAILURE); }
        n->value = v;
        n->left = n->right = NULL;
        *root = n;
        return;
    }

    if (v < (*root)->value)
        insert(&(*root)->left, v);
    else if (v > (*root)->value)
        insert(&(*root)->right, v);
    /* equal → ignore */
}

/* Helper for printing a value with optional leading space. */
static void print_value(long v, bool *first)
{
    if (!*first)
        putchar(' ');
    printf("%ld", v);
    *first = false;
}

/* Traversals */
static void inorder(Node *root, bool *first)
{
    if (!root) return;
    inorder(root->left, first);
    print_value(root->value, first);
    inorder(root->right, first);
}

static void preorder(Node *root, bool *first)
{
    if (!root) return;
    print_value(root->value, first);
    preorder(root->left, first);
    preorder(root->right, first);
}

static void postorder(Node *root, bool *first)
{
    if (!root) return;
    postorder(root->left, first);
    postorder(root->right, first);
    print_value(root->value, first);
}

/* Free the whole tree (not required for the observed behaviour,
   but good practice). */
static void free_tree(Node *root)
{
    if (!root) return;
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main(int argc, char *argv[])
{
    if (argc < 2) {                     /* no mode supplied */
        puts("INVALID_MODE");
        return 0;
    }

    const char *mode = argv[1];
    bool valid_mode = (strcmp(mode, "in") == 0 ||
                       strcmp(mode, "pre") == 0 ||
                       strcmp(mode, "post") == 0);

    if (!valid_mode) {
        puts("INVALID_MODE");
        return 0;
    }

    /* Build the BST from the remaining arguments.
       The original binary processed at most 64 numbers when more
       than 66 arguments were given. */
    int max_numbers = (argc > 66) ? 64 : argc - 2;
    Node *root = NULL;

    for (int i = 0; i < max_numbers; ++i) {
        const char *num_str = argv[2 + i];
        char *endptr;
        long v = strtol(num_str, &endptr, 10);
        if (*endptr != '\0')   /* ignore non‑numeric arguments */
            continue;
        insert(&root, v);
    }

    if (root == NULL) {
        puts("EMPTY");
        return 0;
    }

    bool first = true;
    if (strcmp(mode, "in") == 0) {
        inorder(root, &first);
    } else if (strcmp(mode, "pre") == 0) {
        preorder(root, &first);
    } else { /* "post" */
        postorder(root, &first);
    }
    putchar('\n');

    free_tree(root);
    return 0;
}
